code='''def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    vals=[v for row in g for v in row if v not in (0,2,4)]
    # The route is drawn in the non-wall guide colour.  Walls form long straight lines.
    from collections import Counter
    counts=Counter(vals)
    wall=max(counts,key=lambda v: sum(row.count(v) for row in g))
    # In these tasks, the guide has 2-markers; otherwise it is the colour of 4's row.
    twos={(r,c) for r in range(h) for c in range(w) if g[r][c]==2}
    guide=g[twos.pop()][0] if False else None
    if twos:
        guide=next(g[r][c] for r in range(h) for c in range(w) if g[r][c] not in (0,2,4) and any(abs(r-a)+abs(c-b)==1 for a,b in twos))
    else:
        fours=[(r,c) for r in range(h) for c in range(w) if g[r][c]==4]
        guide=g[fours[0][0]][fours[0][1]-1]
    # Preserve the other (maze) colour, erase guide-colour decoys, then restore route.
    for r in range(h):
        for c in range(w):
            if g[r][c]==guide: g[r][c]=0
    # Components of nonzero guide/marker cells after temporarily using original guide pixels.
    orig=[r[:] for r in grid]
    active={(r,c) for r in range(h) for c in range(w) if orig[r][c] in (guide,2,4)}
    comps=[]
    while active:
        seed=active.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(r+dr,c+dc)
                if q in active: active.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    # Greedily bridge aligned components; actual routes have short, straight gaps.
    changed=True
    while changed:
        changed=False
        best=None
        for i,A in enumerate(comps):
            for j,B in enumerate(comps):
                if i>=j: continue
                for a in A:
                    for b in B:
                        if a[0]==b[0] or a[1]==b[1]:
                            d=abs(a[0]-b[0])+abs(a[1]-b[1])
                            if d>1 and (best is None or d<best[0]): best=(d,i,j,a,b)
        if best:
            _,i,j,a,b=best
            r0,r1=sorted((a[0],b[0])); c0,c1=sorted((a[1],b[1]))
            bridge={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}
            comps[i]=comps[i]|comps[j]|bridge; comps.pop(j); changed=True
    # Keep components containing markers, plus connected original route pieces.
    keep=set()
    for comp in comps:
        if any(orig[r][c] in (2,4) for r,c in comp) or len(comps)==1: keep |= comp
    for r,c in keep: g[r][c]=guide
    return g
'''
