code='''def transform(grid):
    g=[r[:] for r in grid]; h,w=len(g),len(g[0])
    twos=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    fours=[(r,c) for r in range(h) for c in range(w) if g[r][c]==4]
    if twos:
        # Ink next to a two marker; connector is the other non-wall ink on its row.
        r,c=twos[0]
        drawing=next(g[r+dr][c+dc] for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc] not in (0,2,4))
        connector=next(v for v in g[r] if v not in (0,2,4,drawing))
    else:
        r,c=fours[0]; drawing=connector=g[r][c-1]
    active={(r,c) for r in range(h) for c in range(w) if g[r][c] in (drawing,2,4)}
    comps=[]
    while active:
        q=active.pop(); comp={q}; stack=[q]
        while stack:
            r,c=stack.pop()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                z=(r+dr,c+dc)
                if z in active: active.remove(z); comp.add(z); stack.append(z)
        comps.append(comp)
    while len(comps)>1:
        best=None
        for i,A in enumerate(comps):
            for j,B in enumerate(comps):
                if i>=j: continue
                for a in A:
                    for b in B:
                        if a[0]==b[0] or a[1]==b[1]:
                            d=abs(a[0]-b[0])+abs(a[1]-b[1])
                            if best is None or d<best[0]: best=(d,i,j,a,b)
        if best is None: break
        _,i,j,a,b=best; r0,r1=sorted((a[0],b[0])); c0,c1=sorted((a[1],b[1]))
        bridge={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}
        comps[i]|=comps[j]|bridge; comps.pop(j)
    route=comps[0]
    # Remove decoys in the connector colour, then draw the joined route.
    for r in range(h):
        for c in range(w):
            if g[r][c]==connector: g[r][c]=0
    for r,c in route:
        if grid[r][c]!=drawing: g[r][c]=connector
    if fours and not twos:
        r,c=fours[0]
        for cc in range(c,w): g[r][cc]=connector
    return g
